package com.ecoriego.app.network;
import android.os.*; import org.json.*; import java.io.*; import java.net.*; import java.nio.charset.StandardCharsets;
public class WeatherService { public interface Callback{void onResult(double temp,int rain);void onError(String msg);} public static void fetch(final Callback cb){new Thread(()->{try{URL u=new URL("https://api.open-meteo.com/v1/forecast?latitude=-12.05&longitude=-77.04&current=temperature_2m,precipitation&daily=precipitation_probability_max&timezone=auto");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(8000);c.setReadTimeout(8000);c.setRequestMethod("GET");BufferedReader r=new BufferedReader(new InputStreamReader(c.getInputStream(),StandardCharsets.UTF_8));StringBuilder s=new StringBuilder();String x;while((x=r.readLine())!=null)s.append(x);r.close();c.disconnect();JSONObject o=new JSONObject(s.toString());double t=o.getJSONObject("current").getDouble("temperature_2m");int rain=o.getJSONObject("daily").getJSONArray("precipitation_probability_max").getInt(0);new Handler(Looper.getMainLooper()).post(()->cb.onResult(t,rain));}catch(Exception e){new Handler(Looper.getMainLooper()).post(()->cb.onError("No se pudo actualizar el clima. Revisa tu conexión."));}}).start();}}
